#include <cassert>
enum class Phase { Loading, PlayableIntro, MainGame };
enum class Action { MoveRight, Attack, Examine };
struct StepResult {
    bool accepted = false;
    bool meaningful = false;
    bool showHint = false;   // non-modal UI cue
    bool enterMain = false;
};
class Intro {
public:
    void OnRequiredAssetsReady() {
        assert(phase_ == Phase::Loading);
        phase_ = Phase::PlayableIntro;
    }
    StepResult Apply(Action action) {
        StepResult out;
        if (phase_ == Phase::Loading) return out;
        switch (action) {
        case Action::MoveRight:
            if (position_ < 4) { ++position_; out.accepted = true; out.meaningful = true; }
            break;
        case Action::Attack:
            out.accepted = true;  // animation can play even on miss
            if (position_ >= 2 && enemyAlive_) {
                enemyAlive_ = false;
                out.meaningful = true;
            }
            if (!attackHintShown_) {
                attackHintShown_ = true;
                out.showHint = true;
            }
            break;
        case Action::Examine:
            out.accepted = true;
            break;
        }
        if (phase_ == Phase::PlayableIntro && position_ == 4 && !enemyAlive_) {
            phase_ = Phase::MainGame;
            out.enterMain = true;
        }
        return out;
    }
    Phase phase() const { return phase_; }
private:
    Phase phase_ = Phase::Loading;
    int position_ = 0;
    bool enemyAlive_ = true;
    bool attackHintShown_ = false;
};
int main() {
    Intro g;
    assert(!g.Apply(Action::MoveRight).accepted);  // loading
    g.OnRequiredAssetsReady();
    assert(g.Apply(Action::MoveRight).meaningful);
    g.Apply(Action::MoveRight);                      // tile 2
    StepResult firstHit = g.Apply(Action::Attack);
    assert(firstHit.meaningful && firstHit.showHint);
    assert(!g.Apply(Action::Attack).showHint);       // hint once
    g.Apply(Action::MoveRight);
    StepResult exit = g.Apply(Action::MoveRight);
    assert(exit.enterMain && g.phase() == Phase::MainGame);
}
